const out = [];
for (const item of $input.all()) {
  const a = item.json;
  const d = Number(a.daysUntilRenewal);
  const done = Array.isArray(a.completedMilestones) ? a.completedMilestones : [];
  const last = (a.lastCombinedOutreachDaysAgo === null || a.lastCombinedOutreachDaysAgo === undefined) ? null : Number(a.lastCombinedOutreachDaysAgo);
  const base = a.accountId + ':' + a.renewalCycleId + ':';
  let due = false, milestone = null, channels = [], reason = '', actionKey = null, stage = '', next = null;
  if (a.renewalStatus !== 'open') {
    stage = 'resolved'; reason = 'Renewal is ' + a.renewalStatus + ', no further outreach';
  } else if (d > 60) {
    stage = 'waiting'; next = d - 60; reason = 'More than 60 days out, first email milestone not reached';
  } else if (d >= 31) {
    stage = 'email60'; next = d - 30; milestone = 'email60'; actionKey = base + 'email60';
    if (done.includes('email60') || done.includes(actionKey)) { reason = 'Duplicate suppressed: email60 already completed'; }
    else { due = true; channels = ['email']; reason = '31 to 60 days out and email60 not completed'; }
  } else if (d >= 8) {
    stage = 'call30'; next = d - 7; milestone = 'call30'; actionKey = base + 'call30';
    if (done.includes('call30') || done.includes(actionKey)) { reason = 'Duplicate suppressed: call30 already completed'; }
    else { due = true; channels = ['phone']; reason = '8 to 30 days out and call30 not completed (missed email60 skipped)'; }
  } else {
    stage = 'combined_weekly';
    const prior = last !== null || done.includes('combined7');
    if (!prior) {
      milestone = 'combined7'; actionKey = base + 'combined7'; due = true; channels = ['email', 'phone']; next = 7;
      reason = '7 days or less and no prior combined outreach (earlier milestones skipped)';
    } else if (last === null) {
      next = 7; reason = 'Combined outreach recorded without a date, persist last completed combined date';
    } else {
      const bucket = Math.floor((7 - d) / 7);
      milestone = 'weekly'; actionKey = base + 'weekly:' + bucket;
      if (done.includes(actionKey)) { next = 7; reason = 'Duplicate suppressed: weekly action ' + bucket + ' already completed'; }
      else if (last >= 7) { due = true; channels = ['email', 'phone']; next = 7; reason = 'Weekly combined outreach due: ' + last + ' days since last combined action'; }
      else { next = 7 - last; reason = 'Not due: only ' + last + ' days since last combined action'; }
    }
  }
  out.push({ json: {
    ...a,
    cadenceDue: due,
    cadenceStage: stage,
    dueMilestone: milestone,
    actionChannels: channels,
    actionKey: actionKey,
    cadenceReason: reason,
    nextActionDueInDays: next,
    stateUpdateInstructions: 'Demo only, nothing is persisted. In production, after the action is actually completed (not when a draft is created), persist to a durable CRM or database: renewal status, completed milestone (' + (milestone || 'none') + '), last completed combined date, and action key (' + (actionKey || 'none') + '). Check stored action keys before drafting to prevent duplicates across executions.',
  } });
}
return out;

return $input.all().map((item) => {
  const accountName = String(item.json.accountName || '');
  return {
    json: {
      ...item.json,
      linkedInSearchUrl: 'https://www.linkedin.com/search/results/people/?keywords=' + encodeURIComponent(accountName + ' procurement finance'),
      zoomInfoSearchUrl: 'https://www.google.com/search?q=' + encodeURIComponent('site:zoominfo.com ' + accountName + ' procurement finance'),
      contactVerified: false,
      contactVerificationStatus: 'Pending manual review',
      verificationChecklist: 'Confirm company identity, current employer, role in renewal, and contact details before outreach',
    },
  };
});

return $input.all().map((item) => {
  const a = item.json;
  const d = Number(a.daysUntilRenewal);
  const channels = Array.isArray(a.actionChannels) ? a.actionChannels : [];
  const first = String(a.contactName || 'there').split(' ')[0];
  let timing, subjectTail;
  if (d > 0) { timing = 'is coming up in ' + d + (d === 1 ? ' day' : ' days'); subjectTail = 'renewal in ' + d + (d === 1 ? ' day' : ' days'); }
  else if (d === 0) { timing = 'reaches its expiration date today'; subjectTail = 'renewal expires today'; }
  else { timing = 'passed its expiration date ' + Math.abs(d) + (Math.abs(d) === 1 ? ' day' : ' days') + ' ago'; subjectTail = 'renewal expired ' + Math.abs(d) + ' days ago'; }
  let opener;
  if (a.dueMilestone === 'email60') opener = 'I wanted to start the renewal conversation early so you have plenty of time to plan.';
  else if (a.dueMilestone === 'call30') opener = 'I would like to schedule a short call to talk through your renewal.';
  else if (d < 0) opener = 'I wanted to check in again and see how we can help move your renewal forward.';
  else opener = 'I am checking in again to make sure your renewal has the attention it needs.';
  const json = { ...a };
  if (channels.includes('email')) {
    json.emailSubject = a.accountName + ' ' + subjectTail;
    json.emailBody = 'Hi ' + first + ',\n\nYour ' + a.accountName + ' renewal ' + timing + '. ' + opener + ' Please let me know a good time to talk or if there is anything you would like us to review together.\n\nThank you,\nMarcus';
  }
  if (channels.includes('phone')) {
    json.callTask = 'Call ' + a.contactName + ' at ' + a.accountName + ' about the renewal that ' + timing + '. Confirm the contact is verified before dialing, then log the outcome.';
  }
  json.approvalStatus = 'Needs review';
  json.deliveryStatus = 'Not sent';
  json.draftSource = 'Template generated, not AI generated';
  return { json };
});
